function equipmentFootprint(i){const d=dims(i),r=(Number(i.rotation?.[1])||0)*Math.PI/180,w=Math.abs(Math.cos(r))*d[0]*(i.scale?.[0]||1)+Math.abs(Math.sin(r))*d[2]*(i.scale?.[2]||1),z=Math.abs(Math.sin(r))*d[0]*(i.scale?.[0]||1)+Math.abs(Math.cos(r))*d[2]*(i.scale?.[2]||1);return{width:w,depth:z}}
function rectAt(i,x,z){const f=equipmentFootprint(i);return{x1:x-f.width/2,x2:x+f.width/2,z1:z-f.depth/2,z2:z+f.depth/2}}
function overlaps(a,b,g=.01){return a.x1<b.x2-g&&a.x2>b.x1+g&&a.z1<b.z2-g&&a.z2>b.z1+g}
function sortPlacementTargets(){return doc.instances.filter(i=>selected.has(i.id)&&!i.templateId&&!i.testOnly&&i.assetId).sort((a,b)=>{const aa=equipmentFootprint(a),bb=equipmentFootprint(b);return (bb.width*bb.depth-aa.width*aa.depth)||String(a.id).localeCompare(String(b.id))})}

