function buildSpatialIndex(items,cell=2){const buckets=new Map();for(const o of items){for(let ix=Math.floor(o.rect.x1/cell);ix<=Math.floor(o.rect.x2/cell);ix++)for(let iz=Math.floor(o.rect.z1/cell);iz<=Math.floor(o.rect.z2/cell);iz++){const k=ix+','+iz;if(!buckets.has(k))buckets.set(k,[]);buckets.get(k).push(o)}}return {query(r){const seen=new Set(),out=[];for(let ix=Math.floor(r.x1/cell);ix<=Math.floor(r.x2/cell);ix++)for(let iz=Math.floor(r.z1/cell);iz<=Math.floor(r.z2/cell);iz++)for(const o of (buckets.get(ix+','+iz)||[]))if(!seen.has(o)){seen.add(o);out.push(o)}return out.sort((a,b)=>a.originalOrder-b.originalOrder)}}}
