 const out={placed,batch:[],existingCount:placed.length,mode:adapter.optimizationMode,walls,aisles,rejected:{raw:0,floor:0,wall:0,aisle:0,equipment:0},metrics:{floorChecks:0,wallNarrowChecks:0,aisleNarrowChecks:0,existingNarrowChecks:0,batchNarrowChecks:0},indexes:null};
 if(adapter.optimizationMode==='LATTICE_SPATIAL')out.indexes={walls:buildSpatialIndex(walls),aisles:buildSpatialIndex(aisles),existing:buildSpatialIndex(placed)};
