let structureImportPreview=null;
function validateStructureImport(raw){
 const rows=Array.isArray(raw)?raw:(Array.isArray(raw?.instances)?raw.instances:null);
 if(!rows)throw Error('구조도 JSON은 instances 배열이 필요합니다.');
 const allowed=new Set(['building','floor','wall','aisle','zone']);
 const out=rows.map((x,n)=>{
  const templateId=String(x.templateId||x.type||'').toLowerCase();
  if(!allowed.has(templateId))throw Error('허용되지 않은 구조 유형: '+templateId);
  const pos=Array.isArray(x.position)&&x.position.length===3?x.position.map(Number):[0,0,0];
  const rot=Array.isArray(x.rotation)&&x.rotation.length===3?x.rotation.map(Number):[0,0,0];
  const scale=Array.isArray(x.scale)&&x.scale.length===3?x.scale.map(Number):[1,1,1];
  if([...pos,...rot,...scale].some(v=>!Number.isFinite(v)))throw Error('구조도 좌표가 유효하지 않습니다.');
  const t=templates.get(templateId); if(!t)throw Error('현재 계약에 없는 구조 유형: '+templateId);
  const params={width:Number(x.parameters?.width??t.width),length:Number(x.parameters?.length??t.length),height:Number(x.parameters?.height??t.height)};
  if(Object.values(params).some(v=>!Number.isFinite(v)||v<=0))throw Error('구조도 치수가 유효하지 않습니다.');
  return {id:uuid(),assetId:t.assetId||null,entryUsd:null,templateId,equipmentId:null,intakeId:null,label:String(x.label||t.name+' · IMPORT'),position:pos,rotation:rot,scale,parameters:params};
 });
 return out;
}
